import { Component, Input, OnChanges } from '@angular/core';
import { AuthService, User } from '@auth0/auth0-angular';
import { TranslateService } from '@ngx-translate/core';
import { MessageService, TreeNode } from 'primeng/api';
import { DataService } from 'src/app/services/data/data.service';
import FamilyTree from 'src/assets/scripts/familytree';

@Component({
  selector: 'app-my-tree',
  templateUrl: './my-tree.component.html',
  styleUrl: './my-tree.component.scss',
  providers: [MessageService],
})
export class MyTreeComponent implements OnChanges {
  data1: TreeNode[];

  data2: TreeNode[];

  selectedNode: TreeNode;

  nodeHovered: any = null;

  displayDialog: boolean = false;

  newNode = { name: '', avatar: '' };
  @Input() someInputProperty: any;
  userData: any;
  treeData: any;

  constructor(
    private messageService: MessageService,
    private translateService: TranslateService,
    private dataService: DataService,
    private authService: AuthService
  ) {
    this.userData = null;
    this.treeData = null;
  }

  ngOnInit() {
    let language = this.translateService.getDefaultLang();
    this.translateService.getTranslation(language).subscribe((val) => {
      this.data1 = val.FamilyTree;
    });
    this.authService.user$.subscribe((user) => {
        this.userData = user as User;
        console.log(this.userData);
    });

    this.dataService.getUserData().subscribe((data: any) => {
      this.treeData = data;
      this.initFamilyTree();
    });
  }

  private initFamilyTree() {
    const options = this.getOptions();
    const tree = document.getElementById('tree');
    const family = new FamilyTree(tree, {
      mouseScrool: FamilyTree.none,
      scaleInitial: options.scaleInitial,
      mode: 'dark',
      template: 'hugo',  //'hugo','john'
      roots: [4],
      nodeMenu: {
        edit: { text: 'Edit' },
        details: { text: 'Details' },
      },
      nodeTreeMenu: true,
      nodeBinding: {
        field_0: 'name',
        // field_1: 'born',
        img_0: 'photo',
      },
      toolbar: {
                 layout: false,
                 zoom: true,
                 fit: true,
                 expandAll: false,
                 fullScreen: true
             },
      editForm: {
        titleBinding: 'name',
        photoBinding: 'photo',
        addMoreBtn: 'Add element',
        addMore: 'Add more elements',
        addMoreFieldName: 'Element name',
        generateElementsFromFields: true,
        elements: [
          { type: 'textbox', label: 'Full Name', binding: 'name' },
          { type: 'textbox', label: 'Email Address', binding: 'email' },
          [
            { type: 'textbox', label: 'Phone', binding: 'phone' },
            { type: 'date', label: 'Date Of Birth', binding: 'born' },
          ],
          [
            {
              type: 'select',
              options: [
                { value: 'in', text: 'India' },
               
              ],
              label: 'Country',
              binding: 'country',
            },
            { type: 'textbox', label: 'City', binding: 'city' },
          ],
          {
            type: 'textbox',
            label: 'Photo Url',
            binding: 'photo',
            btn: 'Upload',
          },
        ],
      },
    });
    family.on('field', function (sender, args) {
      if (args.name === 'born') {
        const date = new Date(args.value);
        args.value = date.toLocaleDateString();
      }
    });
    family.load(this.treeData.userData);

    family.onUpdateNode((args) => {
      let updatedNode = args.updateNodesData[0] as any;
      if (updatedNode != null || updatedNode != undefined && args.updateNodesData.length > 0) {
        //post the data from args to your server 
        let index = this.treeData.userData.findIndex((item) => item.id === updatedNode.id);
        this.treeData.userData[index] = updatedNode;
        this.dataService.postUserData(this.treeData).subscribe((data: any) => {
          console.log(data);
        });
      }
      else if(args.removeNodeId != null){ 
        let index = this.treeData.userData.findIndex((item) => item.id === args.removeNodeId);
        if (index !== -1) {
            this.treeData.userData.splice(index, 1); 
            this.dataService.postUserData(this.treeData).subscribe((data: any) => {
            console.log(data);
          }); 
       }
      }
     
    });

    family.editUI.on('element-btn-click', function (sender, args) {
      FamilyTree.fileUploadDialog(function (file) {
        let formData = new FormData();
        formData.append('file', file);
        //alert('upload the file');
        console.log(args);
      });
    });
  }

  private getOptions() {
    const searchParams = new URLSearchParams(window.location.search);
    const fit = searchParams.get('fit');
    const enableSearch = true;
    const scaleInitial = fit === 'yes' ? FamilyTree.match.boundary : 1;
    return { enableSearch, scaleInitial };
  }

  showDialog(node: any) {
    this.displayDialog = true;
    this.selectedNode = node;
    this.newNode = { name: '', avatar: '' }; // Reset form fields
  }

  ngOnChanges(changes: any) {
    if (changes.someInputProperty) {
      // Update the expression here...
    }
  }
  addNode() {
    if (!this.selectedNode.children) {
      this.selectedNode.children = [];
    }

    const nodeToAdd = {
      label: this.newNode.name || 'New Node',
      type: 'person',
      styleClass: 'p-person',
      data: { name: this.newNode.name, avatar: this.newNode.avatar },
    };

    this.selectedNode.children.push(nodeToAdd);
    this.displayDialog = false; // Close dialog
  }

  onDialogHide() {
    this.newNode = { name: '', avatar: '' }; // Reset form fields
  }
  onNodeSelect(event) {
    this.messageService.add({
      severity: 'success',
      summary: 'Node Selected',
      detail: event.node.label,
    });
  }
}
